        children: []
      });
    }
    if (format & IS_CODE) {
      actions.appendToParent(localParentNode, {
        type: "inlineCode",
        value: textContent
      });
      return;
    }
    actions.appendToParent(localParentNode, {
      type: "text",
      value: textContent
    });
  }
};
